def _crear_pagina_limpia_wallapop(contexto):
    """
    Crea una pestaña NUEVA para un único anuncio de la cola.

    Antes de abrirla, elimina TODAS las pestañas Wallapop anteriores.
    La sesión/login se conserva porque pertenece al contexto/perfil Chromium.
    """
    actualizar_fase(
        "Pestaña limpia",
        "cerrando pestañas anteriores y abriendo una nueva"
    )

    # Evita acumulación: antes de cada anuncio no debe quedar ninguna
    # pestaña vieja de Wallapop.
    _cerrar_todas_pestanas_wallapop(
        contexto
    )

    try:
        pagina = contexto.new_page()
    except Exception as e:
        raise RuntimeError(
            "No pude crear una pestaña nueva de Wallapop: " + str(e)
        )

    try:
        pagina.goto(
            "https://es.wallapop.com",
            wait_until="domcontentloaded",
            timeout=30000
        )

        pagina.bring_to_front()

        # Pequeña espera para dejar que el frontend termine de iniciar.
        pagina.wait_for_timeout(900)

        _comprobar_sesion_wallapop(pagina)

        if not _pagina_responde_wallapop(
            pagina,
            obtener_config_rendimiento().get(
                "timeout_wallapop",
                12
            )
        ):
            raise RuntimeError(
                "La pestaña nueva de Wallapop no responde correctamente."
            )

        print(
            "Pestaña limpia preparada para el anuncio:",
            pagina.url
        )

        return pagina

    except Exception:
        try:
            if not pagina.is_closed():
                pagina.close()
        except Exception:
            pass

        raise

