def _crear_pagina_limpia_wallapop(contexto):
    """V131: reutiliza una pestaña Wallapop viva y entra al flujo de subida."""
    actualizar_fase("Pestaña Wallapop", "reutilizando sesión activa")
    try:
        paginas=[q for q in contexto.pages if not q.is_closed()]
    except Exception:
        paginas=[]
    wallapop=[]
    for q in paginas:
        try:
            if "wallapop.com" in (q.url or "").lower(): wallapop.append(q)
        except Exception: pass
    pagina=wallapop[-1] if wallapop else (paginas[-1] if paginas else contexto.new_page())
    for q in wallapop:
        if q is pagina: continue
        try: q.close(run_before_unload=False)
        except TypeError:
            try: q.close()
            except Exception: pass
        except Exception: pass
    try:
        if "/app/catalog/upload" not in (pagina.url or "").lower():
            pagina.goto("https://es.wallapop.com/app/catalog/upload",wait_until="domcontentloaded",timeout=30000)
        pagina.bring_to_front()
        pagina.wait_for_timeout(1400)
        _comprobar_sesion_wallapop(pagina)
        if not _pagina_responde_wallapop(pagina,obtener_config_rendimiento().get("timeout_wallapop",12)):
            raise RuntimeError("Wallapop no respondió al preparar la publicación.")
        return pagina
    except Exception:
        raise

